@namespace sv_ce7b6f3ca5ad4c7e811d1acec227888d.Components.Pages.Apply
@using sv_ce7b6f3ca5ad4c7e811d1acec227888d.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo"
                              OnNext="NextStep"
                              ValidateEmail="ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;
        case 2:
            <ReferencesStep References="references"
                            OnNext="NextStep"
                            OnBack="PrevStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="UpdateCoverLetter"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        OnBack="PrevStep"
                        OnEditStep="GoToStep"
                        OnSubmit="SubmitAsync" />
            break;
    }
